{"command": "cd /workspace/work && python3 - <<'EOF'
import numpy as np, wave
w=wave.open("p6.wav"); sr=w.getframerate(); n=w.getnframes()
d=np.frombuffer(w.readframes(n),dtype='<i2').reshape(-1,2).astype(float).mean(1)
# arpeggio G3+037 cycles G3(196) Bb3(233.1) D4(293.7) each tick (5.83ms)
def band_e(sig,f):
    t=np.arange(len(sig))/sr
    c=np.exp(-2j*np.pi*f*t)
    return np.abs(sig*np.hanning(len(sig))*c).sum()
seg=d[0:int(sr*0.35)]
# short-time energy at each candidate freq, 8ms hops
hop=int(sr*0.008); win=int(sr*0.012)
res={f:[] for f in [196,233.1,293.7]}
for s in range(0,len(seg)-win,hop):
    x=seg[s:s+win]*np.hanning(win)
    t=np.arange(win)/sr
    for f in res:
        res[f].append(abs((x*np.exp(-2j*np.pi*f*t)).sum()))
import sys
for f,v in res.items():
    v=np.array(v); print(f, " ".join("%d"%(x) for x in v[:40]))
EOF"}

